@echo off
rem ==== Hands Engine Library Setup ==== 
set "VENV=%~dp0venv"
if not exist "%VENV%" (
    python -m venv "%VENV%"
)
call "%VENV%\Scripts\activate.bat"
python -m pip install --upgrade pip
python -m pip install -r requirements.txt
echo.
echo ==== Setup Complete. Use the environment with: =====
echo   %VENV%\Scripts\activate.bat
pause
